#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

int main() {
    int n; if (!(cin >> n)) return 0;
    vector<int> a(n);
    bool has0 = false; int sum = 0;
    for (int i = 0; i < n; ++i) { cin >> a[i]; if (a[i] == 0) has0 = true; sum += a[i]; }
    if (!has0) { cout << -1 << "\n"; return 0; }
    sort(a.rbegin(), a.rend());
    int rem = sum % 3;
    if (rem != 0) {
        int del1 = -1;
        for (int i = n - 1; i >= 0; --i) if (a[i] % 3 == rem) { del1 = i; break; }
        if (del1 != -1) a.erase(a.begin() + del1);
        else {
            int d1 = -1, d2 = -1;
            for (int i = n - 1; i >= 0; --i) {
                if (a[i] % 3 == 3 - rem) {
                    if (d1 == -1) d1 = i;
                    else if (d2 == -1) { d2 = i; break; }
                }
            }
            if (d1 != -1 && d2 != -1) { a.erase(a.begin() + d1); a.erase(a.begin() + d2); }
            else { cout << -1 << "\n"; return 0; }
        }
    }
    if (a.empty() || a[0] == 0) { cout << 0 << "\n"; return 0; }
    for (int x : a) cout << x;
    cout << "\n";
    return 0;
}

