#include <algorithm>
using namespace std;

int main() {
    int n; long long k; cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    sort(a.begin(), a.end());
    int best_len = 0; long long best_val = a[0];
    long long cur_sum = 0;
    int j = 0;
    for (int i = 0; i < n; ++i) {
        if (i > 0) cur_sum += (a[i] - a[i - 1]) * (i - j);
        while (cur_sum > k) {
            cur_sum -= (a[i] - a[j]);
            j++;
        }
        if (i - j + 1 > best_len) {
            best_len = i - j + 1;
            best_val = a[i];
        }
    }
    cout << best_len << " " << best_val << "\n";
    return 0;
}

