    int n = v.size();
    for (int mask = 0; mask < (1 << n); ++mask) {
        long long s = 0;
        for (int i = 0; i < n; ++i) if (mask & (1 << i)) s += v[i];
        if (s <= limit) res.push_back(s);
    }
}

